ee:variables.ee:set-variable:
%dw 2.0
output application/json
import * from dw::Runtime
var startDateValidation = now() as DateTime as String {
	format: "yyyy-MM-dd"
} <= (payload.checkinDate default now() as DateTime as String {
	format: "yyyy-MM-dd"
} + |P1D|) default true
var endDateValidation = (payload.checkinDate default now() as DateTime as String {
	format: "yyyy-MM-dd"
}) <= (payload.checkoutDate default now() as DateTime as String {
	format: "yyyy-MM-dd"
} + |P2D|) default true
---
if(startDateValidation != true)
fail("checkinDate should be equal or greater than current date")
else if(endDateValidation != true)
fail("checkoutDate should be equal or greater than checkinDate")
else if(sizeOf(payload.propertyCode)  == 0)
fail("Atleast 1 propertyCode is required in the request")
else if(payload.propertyListing == false and sizeOf(payload.propertyCode) > 1)
fail("Only one propertyCode is allowed when propertyListing is false")
else if(payload.propertyListing == true and sizeOf(payload.propertyCode) > 3)
fail("Maximum 3 properties are allowed when propertyListing is true")
else if((!isEmpty(payload.voucherCode) and !isEmpty(payload.promotionCode)) or
(!isEmpty(payload.promotionCode) and !isEmpty(payload.corporateCode)) or
(!isEmpty(payload.voucherCode) and !isEmpty(payload.corporateCode))
 )
fail("Only one element from voucherCode, promotionCode and corporateCode is allowed.")
else {
	Result: "Validation Done"
}

ee:message.ee:set-payload:
%dw 2.0
output application/json
---
if (payload.errorCategory == "voucher")
payload - "errorCategory"
else
{
	messageId: payload.messageId,
	propertyList: (payload.propertyList default []) map(property) ->
	(property ++ 
		{
	"rateType":(Mule::p('apartmentdetails.rateType') splitBy ",") map trim($)}
	)
}

ee:variables.ee:set-variable:
%dw 2.0 output application/json // this is to restrict over 512 KB data logging for new-relic var pData = if((sizeOf(payload.^raw) default 0) < 500000) payload
else
{ "checkAvailabilityV3Response": "checkAvailabilityV3 Response Recieved", } --- { "Source_App_ID" : p('application.targetApp'), "Target_App_ID" : p('application.sourceApp'), "Interface_ID" :p('inteface.experience'), "Event_Category_ID" : p('category.info'), "Operation" : p('operation.bookingV2'), "Correlation_ID" : vars.reqVar.messageId, "Message_ID" : vars.reqVar.messageId, "Process" : "BookingSearchResult-ApartmentDetailsV3Response", "HotelCode" : "", "Source_ID" : "", "Target_ID" : "", "Integration_Status" : "Success", "Functional_Response_Comments" : "", "Functional_Response_Status" : "Success", "Created_On" : (now() + |PT8H|), "Reference_Metadata" : "", "Payload" : write(pData, "application/json"), "Error_Details" :"" , "Error_StackTrace" : "", "Payload_Mime_Type" : payload.^mimeType }
